import{_ as s,a0 as n,w as p,s as r,I as i,x as t,a1 as e,A as a,ao as u}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"如何為登錄和 sudo 設置雙因子認證 | LCTT x X-CMD","titleTemplate":false,"description":"如何為登錄和 sudo 設置雙因子認證 | LCTT (201606) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何為登錄和 sudo 設置雙因子認證 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何為登錄和 sudo 設置雙因子認證 | LCTT (201606) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201606/20160513 How to Set Up 2-Factor Authentication for Login and sudo","title":"如何為登錄和 sudo 設置雙因子認證","tag":"201606","desc":""},"relativePath":"201606/20160513 How to Set Up 2-Factor Authentication for Login and sudo.md","filePath":"[post].md"}'),d={name:"201606/20160513 How to Set Up 2-Factor Authentication for Login and sudo.md"};function g(h,o,c,m,f,k){const l=n("Link");return p(),r("div",null,[o[11]||(o[11]=i("h1",{id:"如何為登錄和-sudo-設置雙因子認證",tabindex:"-1"},[t("如何為登錄和 sudo 設置雙因子認證 "),i("a",{class:"header-anchor",href:"#如何為登錄和-sudo-設置雙因子認證","aria-label":"Permalink to “如何為登錄和 sudo 設置雙因子認證”"},"​")],-1)),o[12]||(o[12]=i("p",null,[i("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/auth_crop.png?itok=z_cdYZZf",alt:""})],-1)),i("p",null,[o[1]||(o[1]=t("安全就是一切。我們生活的當今世界，數據具有令人難以置信的價值，而你也一直處於數據丟失的風險之中。因此，你必須想盡辦法保證你桌面系統和服務器中數據的安全。結果，管理員和用户就會創建極其複雜的密碼、使用密碼管理器甚至其它更復雜的東西。但是，如果我告訴你你可以只需要一步，至多兩步就能登錄到你的 Linux 服務器或桌面系統中呢？多虧了 ",-1)),e(l,{href:"https://play.google.com/store/apps/details?id=com.google.android.apps.authenticator2"},{default:a(()=>[...o[0]||(o[0]=[t("Google 身份驗證器",-1)])]),_:1}),o[2]||(o[2]=t("，現在你可以做到了。並且，配置也極其簡單。",-1))]),o[13]||(o[13]=u('<p>我會給你簡要介紹為登錄和 sudo 設置雙因子認證的步驟。我基於 Ubuntu 16.04 桌面系統進行介紹，但這些步驟也適用於其它服務器。為了實現雙因子認證，我會使用 Google 身份驗證器。</p><p>這裏有個非常重要的警告：一旦你設置了認證，沒有一個從認證器中獲得的由 6 個數字組成的驗證碼你就不可能登錄賬户（或者執行 sudo 命令）。這也給你增加了一步額外的操作，因此如果你不想每次登錄到 Linux 服務器（或者使用 sudo）的時候都要拿出你的智能手機，這個方案就不適合你。但你也要記住，這額外的一個步驟也給你帶來一層其它方法無法給予的保護。</p><p>話不多説，開始吧。</p><h3 id="安裝必要的組件" tabindex="-1">安裝必要的組件 <a class="header-anchor" href="#安裝必要的組件" aria-label="Permalink to “安裝必要的組件”">​</a></h3><p>安裝 Google 身份驗證器（Google Authenticator），首先要解決兩個問題。一是安裝智能機應用。下面是如何從 Google 應用商店安裝的方法：</p><ol><li>在你的安卓設備中打開 Google 應用商店</li><li>搜索 google 身份驗證器</li><li>找到並點擊有 Google Inc. 標識的應用</li><li>點擊安裝</li><li>點擊“接受”</li><li>等待安裝完成</li></ol><p>接下來，我們繼續在你的 Linux 機器上安裝這個認證器。步驟如下：</p><ol><li>打開一個終端窗口</li><li>輸入命令 sudo apt-get install google-authenticator</li><li>輸入你的 sudo 密碼並敲擊回車</li><li>如果有彈窗提示，輸入 y 並敲擊回車</li><li>等待安裝完成</li></ol><p>接下來配置使用 google-authenticator 進行登錄。</p><h3 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to “配置”">​</a></h3><p>要為登錄和 sudo 添加雙因子認證只需要編輯一個文件，即 /etc/pam.d/common-auth。打開並找到如下一行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>auth    [success=1 default=ignore]      pam_unix.so nullok_secure</span></span></code></pre></div><p>在這行上面添加：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>auth required pam_google_authenticator.so</span></span></code></pre></div><p>保存並關閉文件。</p><p>下一步就是為系統中的每個用户設置 google-authenticator（否則他們就不能登錄了）。為了簡單起見，我們假設你的系統中有兩個用户：jack 和 olivia。首先為 jack 設置（我們假設這是我們一直使用的賬户）。</p><p>打開一個終端窗口並輸入命令 google-authenticator。之後會問你一系列的問題（每個問題你都應該用 y 回答）。問題包括：</p><ul><li>是否允許更新你的 &quot;/home/jlwallen/.google_authenticator&quot; 文件 (y/n) y</li><li>是否禁止多個用户使用同一個認證令牌？這會限制你每 30 秒內只能登錄一次，但能增加你注意到甚至防止中間人攻擊的可能 (y/n)</li><li>默認情況下令牌時長為 30 秒即可，為了補償客户端和服務器之間可能出現的時間偏差，我們允許使用當前時間之前或之後的其它令牌。如果你無法進行時間同步，你可以把這個時間窗口由默認的 1:30 分鐘增加到 4 分鐘。是否希望如此 (y/n)</li><li>如果你嘗試登錄的計算機沒有針對暴力破解進行加固，你可以為驗證模組啓用速率限制。默認情況下，限制攻擊者每 30 秒不能嘗試登陸超過 3 次。是否啓用速率限制 (y/n)</li></ul><p>一旦完成了問題回答，你就會看到你的密鑰、驗證碼以及 5 個緊急刮碼（emergency scratch code）。把這些刮碼打印出來並保存。你可以在無法使用手機的時候使用它們（每個刮碼僅限使用一次）。密鑰用於你在 Google 身份驗證器上設置賬户，驗證碼是你能當下就能夠立即使用（如果需要）的一次性驗證碼。</p><h3 id="設置應用" tabindex="-1">設置應用 <a class="header-anchor" href="#設置應用" aria-label="Permalink to “設置應用”">​</a></h3><p>現在你已經配置好了用户 jack。在設置用户 olivia 之前，你需要在 Google 身份驗證器應用上為 jack 添加賬户（LCTT 譯註：實際操作情形中，是為 jack 的手機上安裝的該應用創建一個賬户）。在打開應用，點擊“菜單”按鈕（右上角三個豎排點）。點擊“添加賬户”然後點擊“輸入提供的密鑰”。在下一個窗口（圖1），你需要輸入你運行 google-authenticator 應用時提供的 16 個數字的密鑰。給賬户取個名字（以便你記住這用於哪個賬户），然後點擊“添加”。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/floated_images/public/auth_a.png?itok=xSMkd-Mf" alt=""></p><p><em>圖1: 在 Google Authenticator 應用上新建賬户</em></p><p>（LCTT 譯註：Google 身份驗證器也可以掃描你在服務器上設置時顯示的二維碼，而不用手工輸入密鑰）</p><p>添加完賬户之後，你就會看到一個 6 個數字的密碼，你每次登錄或者使用 sudo 的時候都會需要這個密碼。</p><p>最後，在系統上設置其它賬户。正如之前提到的，我們會設置一個叫 olivia 的賬户。步驟如下：</p><ol><li>打開一個終端窗口</li><li>輸入命令 sudo su olivia</li><li>在智能機上打開 Google 身份驗證器</li><li>在終端窗口（圖2）中輸入（應用提供的） 6 位數字驗證碼並敲擊回車</li><li>輸入你的 sudo 密碼並敲擊回車</li><li>以新用户輸入命令 google-authenticator，回答問題並記錄生成的密鑰和驗證碼。</li></ol><p>成功為 olivia 用户設置好之後，用 google-authenticator 命令，在 Google 身份驗證器應用上根據用户信息（和之前為第一個用户添加賬户相同）添加一個新的賬户。現在你在 Google 身份驗證器應用上就會有 jack 和 olivia 兩個賬户了。（LCTT 譯註：在實際操作情形中，通常是為 jack 和 olivia 兩個人的手機分別設置。）</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/auth_b.png?itok=FH36V1r0" alt=""></p><p><em>圖2: 為 sudo 輸入 6位數字驗證碼</em></p><p>好了，就是這些。每次你嘗試登錄系統（或者使用 sudo） 的時候，在你輸入用户密碼之前，都會要求你輸入提供的 6 位數字驗證碼。現在你的 Linux 機器就比添加雙因子認證之前安全多了。雖然有些人會認為這非常麻煩，我仍然推薦使用，尤其是那些保存了敏感數據的機器。</p><hr>',32)),i("p",null,[o[4]||(o[4]=t("via: ",-1)),e(l,{href:"https://www.linux.com/learn/how-set-2-factor-authentication-login-and-sudo"},{default:a(()=>[...o[3]||(o[3]=[t("https://www.linux.com/learn/how-set-2-factor-authentication-login-and-sudo",-1)])]),_:1})]),i("p",null,[o[8]||(o[8]=t("作者：",-1)),e(l,{href:"https://www.linux.com/users/jlwallen"},{default:a(()=>[...o[5]||(o[5]=[t("JACK WALLEN",-1)])]),_:1}),o[9]||(o[9]=t(" 譯者：",-1)),e(l,{href:"http://mutouxiaogui.cn/blog/"},{default:a(()=>[...o[6]||(o[6]=[t("ictlyh",-1)])]),_:1}),o[10]||(o[10]=t(" 校對：",-1)),e(l,{href:"https://github.com/wxy"},{default:a(()=>[...o[7]||(o[7]=[t("wxy",-1)])]),_:1})])])}const _=s(d,[["render",g]]);export{b as __pageData,_ as default};
